name: Claude PR Critique

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  pull-requests: write
  issues: write

jobs:
  build_and_critique:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'npm'

      - name: Install and test web
        run: |
          cd web
          npm ci
          npm run lint
          npm run typecheck
          npm test

      - name: Install and test apps
        run: |
          cd apps
          npm ci
          npm run lint
          npm run typecheck
          npm test

      - name: Install and test electron
        run: |
          cd electron
          npm ci
          npm run lint
          npm run typecheck
          npm test

      - name: Claude PR critique
        uses: actions/github-script@v6
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
        with:
          script: |
            const pr = github.context.payload.pull_request;
            const prNumber = pr.number;
            const owner = github.context.repo.owner;
            const repo = github.context.repo.repo;
            const title = pr.title;
            const body = pr.body || '';
            const diffUrl = pr.diff_url;

            const prompt = `Please provide a short critique of the following pull request:\n\nTitle: ${title}\n\nBody: ${body}\n\nDiff URL: ${diffUrl}\n\nThe critique should be concise and focus on potential issues, improvements, and overall quality.`;

            if (!process.env.ANTHROPIC_API_KEY) {
              core.setFailed('ANTHROPIC_API_KEY is not set');
              return;
            }

            const response = await fetch('https://api.anthropic.com/v1/messages', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01',
              },
              body: JSON.stringify({
                model: 'claude-3-5-sonnet-20240620',
                max_tokens: 200,
                temperature: 0.7,
                messages: [
                  { role: 'user', content: prompt },
                ],
              }),
            });

            if (!response.ok) {
              const errorText = await response.text();
              core.setFailed(`Anthropic API request failed: ${response.status} ${response.statusText} - ${errorText}`);
              return;
            }

            const data = await response.json();
            const critique = data.content?.[0]?.text || 'No critique returned.';

            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number: prNumber,
              body: `**Claude PR Critique**\n\n${critique}`,
            });
